using System.Runtime.CompilerServices;

public static class PagedMerge
{
    public static async IAsyncEnumerable<T> MergeSortedAsync<T>(
        IReadOnlyList<IAsyncEnumerable<T>> streams,
        IComparer<T> comparer,
        [EnumeratorCancellation] CancellationToken ct = default)
    {
        var enumerators = new IAsyncEnumerator<T>?[streams.Count];
        var heap = new PriorityQueue<int, T>(comparer);
        try
        {
            for (var i = 0; i < streams.Count; i++)
            {
                enumerators[i] = streams[i].GetAsyncEnumerator(ct);
                if (await enumerators[i]!.MoveNextAsync().ConfigureAwait(false))
                    heap.Enqueue(i, enumerators[i]!.Current);
            }
            while (heap.TryDequeue(out var streamIndex, out var value))
            {
                yield return value;
                var en = enumerators[streamIndex]!;
                if (await en.MoveNextAsync().ConfigureAwait(false))
                    heap.Enqueue(streamIndex, en.Current);
            }
        }
        finally
        {
            foreach (var en in enumerators)
                if (en is not null) await en.DisposeAsync().ConfigureAwait(false);
        }
    }
}
